(window.V2_TALK=window.V2_TALK||{})["mairie"]={"mairie/mairie":[{"id":"V_mairie_mairie_01","title":"La carte d'identité de Léa","premise":"Mom applies for Léa's ID card and passport.","cefr":"A2","lines":[{"speaker":"L'employée","fr":"Bonjour, madame. Vous avez rendez-vous ?","en":"Hello, madam. Do you have an appointment?","spans":[[27,38,"fr_rendez_vous_noun"]]},{"speaker":"Maman","fr":"Oui, à dix heures, pour la carte d'identité de ma fille.","en":"Yes, at ten, for my daughter's identity card.","spans":[[27,43,"fr_carte_identite_noun"]]},{"speaker":"L'employée","fr":"Très bien. Vous avez la photo ?","en":"Very good. Do you have the photo?","spans":[[24,29,"fr_photo_noun"]]},{"speaker":"Léa","fr":"Oui, la voilà. Je ne souris pas, c'est interdit !","en":"Yes, here it is. I'm not smiling; it's not allowed!","spans":[]},{"speaker":"L'employée","fr":"C'est parfait. Et vous faites aussi le passeport ?","en":"That's perfect. And are you doing the passport as well?","spans":[[39,48,"fr_passeport_noun"]]},{"speaker":"Maman","fr":"Oui, on part en Angleterre cet été.","en":"Yes, we're going to England this summer.","spans":[]},{"speaker":"L'employée","fr":"Alors signez ici, madame. Et toi, Léa, tu sais écrire ton nom ?","en":"Then sign here, madam. And you, Léa, can you write your name?","spans":[[6,12,"fr_signer_verb"],[47,53,"fr_ecrire_verb"],[58,61,"fr_nom_noun"]]},{"speaker":"Léa","fr":"Bien sûr ! L, É, A !","en":"Of course! L, É, A!","spans":[]},{"speaker":"L'employée","fr":"Bravo. Maintenant, il faut attendre trois semaines.","en":"Well done. Now you have to wait three weeks.","spans":[[27,35,"fr_attendre_verb"]]}]},{"id":"V_mairie_mairie_02","title":"La file d'attente","premise":"Grandpa and Mr. Blanc chat in line.","cefr":"A2","lines":[{"speaker":"Papi Henri","fr":"Pardon, c'est la file pour l'état civil ?","en":"Excuse me, is this the line for the registry office?","spans":[[17,21,"fr_file_noun"]]},{"speaker":"M. Blanc","fr":"Oui, mais il faut attendre. Il y a six personnes devant nous.","en":"Yes, but you'll have to wait. There are six people ahead of us.","spans":[[18,26,"fr_attendre_verb"]]},{"speaker":"Papi Henri","fr":"Ah, monsieur Blanc ! Vous venez pour quoi ?","en":"Ah, Mr. Blanc! What are you here for?","spans":[]},{"speaker":"M. Blanc","fr":"Je change d'adresse. J'habite maintenant au-dessus du garage.","en":"I'm changing my address. I live above the garage now.","spans":[[12,19,"fr_adresse_noun"]]},{"speaker":"Papi Henri","fr":"Moi, je viens chercher un papier pour ma retraite.","en":"I've come for a document for my pension.","spans":[]},{"speaker":"M. Blanc","fr":"Regardez, le bureau numéro deux est libre !","en":"Look, desk number two is free!","spans":[[13,19,"fr_bureau_noun"]]},{"speaker":"Papi Henri","fr":"Enfin ! Allez-y, vous étiez là avant moi.","en":"At last! Go ahead, you were here before me.","spans":[]}]},{"id":"V_mairie_mairie_03","title":"Interview de madame la maire","premise":"Tom interviews the mayor for the school newspaper.","cefr":"A2","lines":[{"speaker":"Tom","fr":"Bonjour, madame la maire. Je peux vous poser des questions pour le journal de l'école ?","en":"Hello, Madam Mayor. Can I ask you some questions for the school newspaper?","spans":[[19,24,"fr_maire_noun"]]},{"speaker":"Mme Lefort","fr":"Avec plaisir, Tom. Assieds-toi dans mon bureau.","en":"With pleasure, Tom. Sit down in my office.","spans":[[40,46,"fr_bureau_noun"]]},{"speaker":"Tom","fr":"Qu'est-ce que fait un maire ?","en":"What does a mayor do?","spans":[[22,27,"fr_maire_noun"]]},{"speaker":"Mme Lefort","fr":"Beaucoup de choses ! Les écoles, les routes, les poubelles, les mariages…","en":"Lots of things! Schools, roads, trash cans, weddings…","spans":[[49,58,"fr_poubelle_noun"]]},{"speaker":"Tom","fr":"Les poubelles aussi ?","en":"Trash cans too?","spans":[[4,13,"fr_poubelle_noun"]]},{"speaker":"Mme Lefort","fr":"Oui ! Un village propre, c'est important.","en":"Yes! A clean village is important.","spans":[]},{"speaker":"Tom","fr":"Et pourquoi il y a deux drapeaux devant la mairie ?","en":"And why are there two flags in front of the town hall?","spans":[[24,32,"fr_drapeau_noun"]]},{"speaker":"Mme Lefort","fr":"Le drapeau français et le drapeau européen. Tu écris tout ça ?","en":"The French flag and the European flag. Are you writing all that down?","spans":[[3,10,"fr_drapeau_noun"],[26,33,"fr_drapeau_noun"],[47,52,"fr_ecrire_verb"]]},{"speaker":"Tom","fr":"Oui ! Et je mets votre nom en gros titre !","en":"Yes! And I'm putting your name in the headline!","spans":[[23,26,"fr_nom_noun"]]}]}],"mairie/bureau":[{"id":"V_mairie_bureau_01","title":"Une lettre pour Emily","premise":"Léa writes to her English pen pal.","cefr":"A1","lines":[{"speaker":"Léa","fr":"Maman, tu as un stylo ? J'écris une lettre à Emily, ma correspondante anglaise.","en":"Mom, do you have a pen? I'm writing a letter to Emily, my English pen pal.","spans":[[16,21,"fr_stylo_noun"],[36,42,"fr_lettre_noun"]]},{"speaker":"Maman","fr":"Tiens. Tu écris en français ou en anglais ?","en":"Here. Are you writing in French or in English?","spans":[]},{"speaker":"Léa","fr":"Les deux ! Moitié-moitié.","en":"Both! Half and half.","spans":[]},{"speaker":"Maman","fr":"Bonne idée. Voilà une enveloppe. N'oublie pas l'adresse.","en":"Good idea. Here's an envelope. Don't forget the address.","spans":[[22,31,"fr_enveloppe_noun"]]},{"speaker":"Léa","fr":"Et il faut quel timbre pour l'Angleterre ?","en":"And what stamp do you need for England?","spans":[[16,22,"fr_timbre_noun"]]},{"speaker":"Maman","fr":"Un timbre international. On l'achète à la poste demain.","en":"An international stamp. We'll buy it at the post office tomorrow.","spans":[[3,9,"fr_timbre_noun"]]}]},{"id":"V_mairie_bureau_02","title":"Les clés de madame la maire","premise":"The mayor can't find her keys.","cefr":"A1","lines":[{"speaker":"Mme Lefort","fr":"Où sont mes clés ? Elles étaient sur mon bureau !","en":"Where are my keys? They were on my desk!","spans":[[12,16,"fr_cle_noun"]]},{"speaker":"L'employée","fr":"Sous l'enveloppe, peut-être ?","en":"Under the envelope, maybe?","spans":[[7,16,"fr_enveloppe_noun"]]},{"speaker":"Mme Lefort","fr":"Non… Il y a seulement des lettres et mon stylo.","en":"No… There are only letters and my pen.","spans":[[26,33,"fr_lettre_noun"],[41,46,"fr_stylo_noun"]]},{"speaker":"L'employée","fr":"Et dans votre poche ?","en":"And in your pocket?","spans":[]},{"speaker":"Mme Lefort","fr":"Ah ! Les voilà. Merci, je perds toujours tout !","en":"Ah! Here they are. Thanks, I'm always losing things!","spans":[]},{"speaker":"L'employée","fr":"C'est normal, vous avez beaucoup de travail.","en":"It's understandable; you have a lot of work.","spans":[]}]},{"id":"V_mairie_bureau_03","title":"La collection de timbres","premise":"Grandpa shows Tom his stamp collection.","cefr":"A2","lines":[{"speaker":"Papi Henri","fr":"Tom, regarde ma collection de timbres.","en":"Tom, look at my stamp collection.","spans":[[30,37,"fr_timbre_noun"]]},{"speaker":"Tom","fr":"Il y en a beaucoup ! Celui-là, il vient d'où ?","en":"There are loads! Where's this one from?","spans":[]},{"speaker":"Papi Henri","fr":"Du Japon. Un ami m'a envoyé une lettre en 1975.","en":"From Japan. A friend sent me a letter in 1975.","spans":[[32,38,"fr_lettre_noun"]]},{"speaker":"Tom","fr":"Et tu as gardé l'enveloppe ?","en":"And you kept the envelope?","spans":[[17,26,"fr_enveloppe_noun"]]},{"speaker":"Papi Henri","fr":"Oui, toutes les enveloppes. Les timbres sont plus beaux dessus.","en":"Yes, all the envelopes. The stamps look nicer on them.","spans":[[16,26,"fr_enveloppe_noun"],[32,39,"fr_timbre_noun"]]},{"speaker":"Tom","fr":"Moi, je reçois seulement des e-mails…","en":"I only get e-mails…","spans":[]},{"speaker":"Papi Henri","fr":"Alors écris-moi une vraie lettre, et je te réponds !","en":"Then write me a real letter, and I'll write back!","spans":[[26,32,"fr_lettre_noun"]]}]}],"mairie/poste":[{"id":"V_mairie_poste_03","title":"L'affiche de la fête","premise":"Léa reads the poster for the village fête.","cefr":"A1","lines":[{"speaker":"Léa","fr":"Sophie, c'est quoi, cette affiche ?","en":"Sophie, what's this poster?","spans":[[26,33,"fr_affiche_noun"]]},{"speaker":"Sophie","fr":"C'est pour la fête du village. Regarde la date : le 14 juillet.","en":"It's for the village fête. Look at the date: July 14.","spans":[[42,46,"fr_date_noun"]]},{"speaker":"Léa","fr":"Oh non, on part en vacances le 12 !","en":"Oh no, we're going on vacation on the 12th!","spans":[]},{"speaker":"Sophie","fr":"Vous allez où ?","en":"Where are you going?","spans":[]},{"speaker":"Léa","fr":"En Angleterre. Ma valise est déjà prête !","en":"To England. My suitcase is already packed!","spans":[[18,24,"fr_valise_noun"]]},{"speaker":"Sophie","fr":"En octobre ? Tu es très organisée !","en":"In October? You're very organized!","spans":[]},{"speaker":"Léa","fr":"Bon… il y a seulement mon passeport et mon doudou dedans.","en":"Well… there's only my passport and my cuddly toy in it.","spans":[]}]},{"id":"V_mairie_poste_01","title":"Un colis pour Marseille","premise":"Dad sends books to his brother.","cefr":"A2","lines":[{"speaker":"Papa","fr":"Bonjour, je voudrais envoyer ce colis à Marseille.","en":"Hello, I'd like to send this package to Marseille.","spans":[[21,28,"fr_envoyer_verb"],[32,37,"fr_colis_noun"]]},{"speaker":"Sophie","fr":"Bien sûr. Qu'est-ce qu'il y a dans le carton ?","en":"Of course. What's in the box?","spans":[[38,44,"fr_carton_noun"]]},{"speaker":"Papa","fr":"Des livres pour mon frère.","en":"Some books for my brother.","spans":[]},{"speaker":"Sophie","fr":"Il est mal emballé : le carton est ouvert ici. Je vous donne du scotch ?","en":"It's badly wrapped: the box is open here. Should I give you some tape?","spans":[[11,18,"fr_emballer_verb"],[24,30,"fr_carton_noun"]]},{"speaker":"Papa","fr":"Oui, merci. Il arrive quand ?","en":"Yes, thanks. When will it arrive?","spans":[]},{"speaker":"Sophie","fr":"Dans trois jours. Voici votre numéro de suivi.","en":"In three days. Here's your tracking number.","spans":[[30,36,"fr_numero_noun"]]},{"speaker":"Papa","fr":"Parfait. Merci, au revoir !","en":"Perfect. Thanks, goodbye!","spans":[]}]},{"id":"V_mairie_poste_02","title":"La nouvelle casquette","premise":"Julien the mailman does his round at the bakery.","cefr":"A2","lines":[{"speaker":"Julien","fr":"Bonjour, madame Roux ! Du courrier pour vous.","en":"Hello, Mrs. Roux! Some mail for you.","spans":[[26,34,"fr_courrier_noun"]]},{"speaker":"Mme Roux","fr":"Merci, Julien. Oh, vous avez une nouvelle casquette !","en":"Thanks, Julien. Oh, you've got a new cap!","spans":[[42,51,"fr_casquette_noun"]]},{"speaker":"Julien","fr":"Oui, l'ancienne est partie avec le vent sur la place !","en":"Yes, the old one blew away in the wind on the square!","spans":[]},{"speaker":"Mme Roux","fr":"Et ce colis, il est pour moi ?","en":"And this package, is it for me?","spans":[[6,11,"fr_colis_noun"]]},{"speaker":"Julien","fr":"Non, pour monsieur Blanc. Mais il ne répond pas. Vous avez son numéro de téléphone ?","en":"No, it's for Mr. Blanc. But he isn't answering. Do you have his phone number?","spans":[[63,69,"fr_numero_noun"],[73,82,"fr_telephone_noun"]]},{"speaker":"Mme Roux","fr":"Oui, je l'appelle tout de suite. Il est sûrement sous une voiture !","en":"Yes, I'll call him straight away. He's probably under a car!","spans":[[10,17,"fr_appeler_verb"]]}]}],"mairie/guichet":[{"id":"V_mairie_guichet_01","title":"Le cadeau pour Tante Julie","premise":"Léa and Tom mail a birthday present.","cefr":"A1","lines":[{"speaker":"Sophie","fr":"Bonjour, les enfants. Qu'est-ce que vous envoyez ?","en":"Hello, children. What are you sending?","spans":[]},{"speaker":"Tom","fr":"Un cadeau pour notre tante. C'est son anniversaire samedi.","en":"A present for our aunt. It's her birthday on Saturday.","spans":[[3,9,"fr_cadeau_noun"]]},{"speaker":"Sophie","fr":"Il faut un paquet solide. Mettez le cadeau dans cette boîte.","en":"You need a sturdy package. Put the present in this box.","spans":[[11,17,"fr_paquet_noun"],[36,42,"fr_cadeau_noun"]]},{"speaker":"Léa","fr":"Je peux mettre un ruban rouge dessus ?","en":"Can I put a red ribbon on it?","spans":[[18,23,"fr_ruban_noun"]]},{"speaker":"Sophie","fr":"Oui, mais sous le papier, sinon il va s'abîmer.","en":"Yes, but under the paper, or it'll get squashed.","spans":[]},{"speaker":"Tom","fr":"Et j'écris l'adresse où ?","en":"And where do I write the address?","spans":[]},{"speaker":"Sophie","fr":"Sur cette étiquette. Écris bien gros !","en":"On this label. Write nice and big!","spans":[[10,19,"fr_etiquette_noun"]]}]},{"id":"V_mairie_guichet_02","title":"Comme avant","premise":"Grandpa wraps a package for Japan the old-fashioned way.","cefr":"A2","lines":[{"speaker":"Papi Henri","fr":"Mademoiselle, vous avez de la ficelle ?","en":"Miss, do you have any string?","spans":[[30,37,"fr_ficelle_noun"]]},{"speaker":"Sophie","fr":"De la ficelle ? Aujourd'hui, on utilise du scotch, monsieur Henri !","en":"String? Nowadays we use tape, Mr. Henri!","spans":[[6,13,"fr_ficelle_noun"]]},{"speaker":"Papi Henri","fr":"Moi, je fais mes paquets avec du papier kraft et de la ficelle. Comme avant.","en":"I wrap my packages in brown paper and string. Like in the old days.","spans":[[17,24,"fr_paquet_noun"],[55,62,"fr_ficelle_noun"]]},{"speaker":"Sophie","fr":"D'accord, voilà la ficelle. Et cette feuille à remplir pour la douane.","en":"OK, here's the string. And this form to fill in for customs.","spans":[[19,26,"fr_ficelle_noun"],[37,44,"fr_feuille_noun_2"]]},{"speaker":"Papi Henri","fr":"Pour la douane ? Pourquoi ?","en":"For customs? Why?","spans":[]},{"speaker":"Sophie","fr":"Votre paquet va au Japon. C'est hors de l'Union européenne.","en":"Your package is going to Japan. That's outside the European Union.","spans":[[6,12,"fr_paquet_noun"]]},{"speaker":"Papi Henri","fr":"Ah, c'est vrai. Bon, je remplis la feuille.","en":"Ah, that's true. Right, I'll fill in the form.","spans":[[35,42,"fr_feuille_noun_2"]]}]},{"id":"V_mairie_guichet_03","title":"La mauvaise étiquette","premise":"A mix-up at the counter turns into a surprise.","cefr":"A2","lines":[{"speaker":"Sophie","fr":"Monsieur Blanc, attendez ! Il y a une erreur sur votre paquet.","en":"Mr. Blanc, wait! There's a mistake on your package.","spans":[[55,61,"fr_paquet_noun"]]},{"speaker":"M. Blanc","fr":"Ah bon ? Quelle erreur ?","en":"Really? What mistake?","spans":[]},{"speaker":"Sophie","fr":"L'étiquette dit « Madame Lefort, mairie ». Ce n'est pas votre paquet !","en":"The label says \"Mrs. Lefort, town hall\". It's not your package!","spans":[[2,11,"fr_etiquette_noun"],[62,68,"fr_paquet_noun"]]},{"speaker":"M. Blanc","fr":"Oh ! Alors où est le mien ? C'est une pièce pour une voiture.","en":"Oh! Then where's mine? It's a car part.","spans":[]},{"speaker":"Sophie","fr":"Ici, je pense. Le petit paquet avec un ruban bleu ?","en":"Here, I think. The little package with a blue ribbon?","spans":[[24,30,"fr_paquet_noun"],[39,44,"fr_ruban_noun"]]},{"speaker":"M. Blanc","fr":"Avec un ruban ? Non, ça, c'est un cadeau !","en":"With a ribbon? No, that's a present!","spans":[[8,13,"fr_ruban_noun"],[34,40,"fr_cadeau_noun"]]},{"speaker":"Sophie","fr":"Ah… Il est pour moi ! C'est mon anniversaire aujourd'hui.","en":"Ah… It's for me! It's my birthday today.","spans":[]},{"speaker":"M. Blanc","fr":"Joyeux anniversaire, Sophie !","en":"Happy birthday, Sophie!","spans":[]}]}],"mairie/polyvalente":[{"id":"V_mairie_polyvalente_01","title":"Le trac de Léa","premise":"Before the village show, Tom talks his shy sister into singing.","cefr":"A2","lines":[{"speaker":"Mme Petit","fr":"Léa, c'est ton tour. Tu montes sur scène ?","en":"Léa, it's your turn. Are you going up on stage?","spans":[]},{"speaker":"Léa","fr":"Je n'ai nullement envie de chanter devant tout le monde…","en":"I have no wish at all to sing in front of everyone…","spans":[[8,17,"fr_nullement_adv"]]},{"speaker":"Tom","fr":"Allez, j'insiste ! Tu chantes véritablement bien.","en":"Come on, I insist! You really sing well.","spans":[[9,16,"fr_insister_verb"],[30,43,"fr_veritablement_adv"]]},{"speaker":"Léa","fr":"Apparemment, tout le village est déjà là.","en":"Apparently the whole village is already here.","spans":[[0,11,"fr_apparemment_adv"]]},{"speaker":"Mme Petit","fr":"Et la scène est rangée proprement. Tout est prêt pour toi.","en":"And the stage is neatly tidied. Everything is ready for you.","spans":[[23,33,"fr_proprement_adv"]]},{"speaker":"Léa","fr":"Bon, d'accord. Mais si je me trompe, c'est totalement ta faute, Tom !","en":"OK, fine. But if I make a mistake, it's totally your fault, Tom!","spans":[[43,53,"fr_totalement_adv"]]},{"speaker":"Tom","fr":"Promis !","en":"Promise!","spans":[]}]}],"mairie/jumelage":[{"id":"V_mairie_jumelage_01","title":"La fête du jumelage","premise":"Guests from the twin towns arrive for the party.","cefr":"A2","lines":[{"speaker":"Mme Lefort","fr":"Bienvenue à la fête du jumelage ! Ce soir, on rassemble tous nos amis d'ailleurs.","en":"Welcome to the twin-towns party! Tonight we're bringing together all our friends from elsewhere.","spans":[[46,55,"fr_rassembler_verb"]]},{"speaker":"Inès","fr":"Il y a un musicien flamand de Belgique et un couple catalan de Gérone !","en":"There's a Flemish musician from Belgium and a Catalan couple from Girona!","spans":[[19,26,"fr_flamand_adj"],[52,59,"fr_catalan_adj"]]},{"speaker":"Tom","fr":"Et le danseur brésilien vient de Rio !","en":"And the Brazilian dancer comes from Rio!","spans":[[14,23,"fr_bresilien_adj"]]},{"speaker":"Papa","fr":"Notre petit village devient cosmopolite.","en":"Our little village is becoming cosmopolitan.","spans":[[28,39,"fr_cosmopolite_adj"]]},{"speaker":"Léa","fr":"Regarde, c'est le fameux flan du boulanger !","en":"Look, it's the baker's famous flan!","spans":[[18,24,"fr_fameux_adj"]]},{"speaker":"Mme Lefort","fr":"Et demain, l'ambassade nous envoie une lettre de félicitations.","en":"And tomorrow the embassy is sending us a letter of congratulations.","spans":[[13,22,"fr_ambassade_noun"]]}]}],"mairie/etatcivil":[{"id":"V_mairie_etatcivil_01","title":"La licence de foot","premise":"Dad signs Tom up for the soccer club at the registry office.","cefr":"A2","lines":[{"speaker":"L'employée","fr":"Bonjour ! Je peux vous aider ?","en":"Hello! Can I help you?","spans":[]},{"speaker":"Papa","fr":"Tom veut une licence au club de foot. Le club demande si nous autorisons Tom à jouer le samedi.","en":"Tom wants a soccer club membership card. The club asks whether we allow Tom to play on Saturdays.","spans":[[13,20,"fr_licence_noun"],[62,72,"fr_autoriser_verb"]]},{"speaker":"L'employée","fr":"Alors remplissez cette fiche, s'il vous plaît.","en":"Then please fill in this form.","spans":[[23,28,"fr_fiche_noun"]]},{"speaker":"Tom","fr":"Statut : élève. C'est bon comme ça ?","en":"Status: student. Is that OK?","spans":[[0,6,"fr_statut_noun"]]},{"speaker":"L'employée","fr":"Parfait. Je mets le tampon de la mairie ici.","en":"Perfect. I'll put the town hall stamp here.","spans":[[20,26,"fr_tampon_noun"]]},{"speaker":"Papa","fr":"Merci ! La gestion des papiers est rapide chez vous.","en":"Thank you! You handle paperwork fast here.","spans":[[11,18,"fr_gestion_noun"]]},{"speaker":"L'employée","fr":"C'est vrai, notre bureau a même reçu un label « accueil rapide » !","en":"That's true, our office even got a 'fast service' label!","spans":[[40,45,"fr_label_noun"]]}]}],"mairie/finances":[{"id":"V_mairie_finances_01","title":"Le budget de la fête","premise":"Grandpa, Léa and the mayor share out the money for the village party.","cefr":"A2","lines":[{"speaker":"Mme Lefort","fr":"Voici le budget annuel du village.","en":"Here is the village's yearly budget.","spans":[[16,22,"fr_annuel_adj"]]},{"speaker":"Papi Henri","fr":"Autrefois, avec la mine, notre village minier était prospère.","en":"In the old days, with the mine, our mining village was prosperous.","spans":[[39,45,"fr_minier_adj"],[52,60,"fr_prospere_adj"]]},{"speaker":"Léa","fr":"Moi aussi, je donne un apport pour la fête : deux euros !","en":"I'm making a contribution to the party too: two euros!","spans":[[23,29,"fr_apport_noun"]]},{"speaker":"Mme Lefort","fr":"Merci, Léa ! Chaque apport compte.","en":"Thank you, Léa! Every contribution counts.","spans":[[20,26,"fr_apport_noun"]]},{"speaker":"Tom","fr":"Les enfants du club de foot réclament un nouveau ballon.","en":"The kids from the soccer club are asking for a new ball.","spans":[[28,37,"fr_reclamer_verb"]]},{"speaker":"Mme Lefort","fr":"On partage en toute équité : un peu pour chacun.","en":"We'll share it out fairly: a little for everyone.","spans":[[20,26,"fr_equite_noun"]]},{"speaker":"Papi Henri","fr":"Et l'euro, Léa, c'est notre unité monétaire.","en":"And the euro, Léa, is our currency unit.","spans":[[34,43,"fr_monetaire_adj"]]}]}],"mairie/vote":[{"id":"V_mairie_vote_01","title":"Le jour des élections","premise":"Léa goes with Dad to vote for the new mayor.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Papa, pourquoi tout le monde vient à la mairie aujourd'hui ?","en":"Dad, why is everyone coming to the town hall today?","spans":[]},{"speaker":"Papa","fr":"C'est le jour des élections. Chaque électeur vient élire le maire.","en":"It's election day. Every voter comes to elect the mayor.","spans":[[36,44,"fr_electeur_noun"],[51,56,"fr_elire_verb"]]},{"speaker":"Léa","fr":"Et le candidat sur l'affiche, il va gagner ?","en":"And the candidate on the poster, is he going to win?","spans":[[6,14,"fr_candidat_noun"]]},{"speaker":"Papa","fr":"On ne sait pas encore. Je vais voter, et ce soir on saura qui est élu.","en":"We don't know yet. I'm going to vote, and tonight we'll know who is elected.","spans":[[31,36,"fr_voter_verb"],[66,69,"fr_elu_noun"]]},{"speaker":"Léa","fr":"Regarde, un partisan agite une pancarte !","en":"Look, a supporter is waving a sign!","spans":[[12,20,"fr_partisan_noun"],[31,39,"fr_pancarte_noun"]]},{"speaker":"Papa","fr":"Et la fanfare joue sous une grande banderole.","en":"And the band is playing under a big banner.","spans":[[35,44,"fr_banderole_noun"]]}]}],"mairie/papiers":[{"id":"V_mairie_papiers_01","title":"Le permis de pêche","premise":"Mom finishes the paperwork for Grandpa's fishing license.","cefr":"A2","lines":[{"speaker":"L'employée","fr":"Votre dossier est presque complet, madame.","en":"Your file is almost complete, ma'am.","spans":[[6,13,"fr_dossier_noun"]]},{"speaker":"Maman","fr":"Il manque un document ?","en":"Is a document missing?","spans":[[13,21,"fr_document_noun"]]},{"speaker":"L'employée","fr":"Non, il manque seulement votre signature, ici.","en":"No, only your signature is missing, here.","spans":[[31,40,"fr_signature_noun"]]},{"speaker":"Maman","fr":"Voilà. C'est pour le permis de pêche de mon père.","en":"There you go. It's for my father's fishing license.","spans":[[21,27,"fr_permis_noun"]]},{"speaker":"L'employée","fr":"Je mets le sceau de la mairie… et je valide le dossier.","en":"I put on the town hall seal… and I approve the file.","spans":[[11,16,"fr_sceau_noun"],[37,43,"fr_valider_verb"],[47,54,"fr_dossier_noun"]]},{"speaker":"Maman","fr":"Merci ! Une démarche simple, pour une fois.","en":"Thank you! A simple procedure, for once.","spans":[[12,20,"fr_demarche_noun"]]}]}],"mairie/honneur":[{"id":"C_R_politics_01","title":"La visite du ministre","premise":"Two neighbors talk about the minister's visit to their town, while a child asks questions.","cefr":"A2","lines":[{"speaker":"Mme Blanc","fr":"Vous savez que le ministre de l'Éducation vient à la mairie demain ?","en":"Did you know the education minister is coming to the town hall tomorrow?","spans":[[18,26,"fr_ministre_noun"],[53,59,"fr_mairie_noun"]]},{"speaker":"M. Petit","fr":"Oui, le maire l'accueille à dix heures. Le commissaire de police a fermé la place.","en":"Yes, the mayor's welcoming him at ten. The police commissioner has closed the square.","spans":[]},{"speaker":"Jules","fr":"C'est le président ?","en":"Is it the president?","spans":[[9,18,"fr_president_noun"]]},{"speaker":"Mme Blanc","fr":"Non, Jules, c'est un ministre. Il travaille pour le gouvernement.","en":"No, Jules, it's a minister. He works for the government.","spans":[[21,29,"fr_ministre_noun"]]},{"speaker":"Jules","fr":"Et une reine, ça vient aussi ?","en":"And do queens come too?","spans":[]},{"speaker":"M. Petit","fr":"Ha ha ! Pas ici. Mais l'année dernière, un prince est venu visiter le château.","en":"Ha ha! Not here. But last year a prince came to visit the château.","spans":[]},{"speaker":"Jules","fr":"Un vrai prince ?","en":"A real prince?","spans":[]},{"speaker":"Mme Blanc","fr":"Oui, avec une couronne... non, je plaisante, en costume-cravate !","en":"Yes, with a crown... no, I'm joking, in a suit and tie!","spans":[]}]},{"id":"V_mairie_honneur_01","title":"Qui est qui ?","premise":"At a reception, the mayor tells Inès who the guests are.","cefr":"A2","lines":[{"speaker":"Mme Lefort","fr":"Bienvenue au salon d'honneur de la mairie, Inès !","en":"Welcome to the town hall's reception hall, Inès!","spans":[[35,41,"fr_mairie_noun"]]},{"speaker":"Inès","fr":"Il y a un vrai ministre ici ?","en":"Is there a real minister here?","spans":[[15,23,"fr_ministre_noun"]]},{"speaker":"Mme Lefort","fr":"Non, mais notre député est venu, et aussi le président du club de musique.","en":"No, but our member of parliament came, and the president of the music club too.","spans":[[16,22,"fr_depute_noun"],[45,54,"fr_president_noun"]]},{"speaker":"Inès","fr":"Et un ministre, il travaille où ?","en":"And where does a minister work?","spans":[[6,14,"fr_ministre_noun"]]},{"speaker":"Mme Lefort","fr":"Dans un ministère, à Paris. Le député, lui, part demain à un congrès.","en":"In a ministry, in Paris. The MP is leaving for a conference tomorrow.","spans":[[8,17,"fr_ministere_noun"],[31,37,"fr_depute_noun"],[61,68,"fr_congres_noun"]]},{"speaker":"Inès","fr":"Et vous, qu'est-ce que vous faites maintenant ?","en":"And what are you doing now?","spans":[]},{"speaker":"Mme Lefort","fr":"Je déclare la fête ouverte ! Et je vous accorde une part de gâteau.","en":"I declare the party open! And I'll give you a slice of cake.","spans":[[3,10,"fr_declarer_verb"],[40,47,"fr_accorder_verb"]]}]}],"mairie/tribune":[{"id":"V_mairie_tribune_01","title":"Le vote du parc","premise":"From the councillors' gallery, Dad and the children watch the town council vote on a new playground.","cefr":"A2","lines":[{"speaker":"Tom","fr":"Papa, ils vont voter pour le nouveau parc de jeux ?","en":"Dad, are they going to vote for the new playground?","spans":[]},{"speaker":"Papa","fr":"Probablement. Mais d'abord, chacun parle.","en":"Probably. But first everyone gets to speak.","spans":[[0,12,"fr_probablement_adv"]]},{"speaker":"Léa","fr":"Le monsieur en cravate parle depuis une heure !","en":"The man in the tie has been talking for an hour!","spans":[]},{"speaker":"Papa","fr":"Il est contre, évidemment. Il dit que le parc coûte trop cher.","en":"He's against it, of course. He says the playground costs too much.","spans":[[15,25,"fr_evidemment_adv"]]},{"speaker":"Tom","fr":"Certes, ça coûte cher, mais les enfants ont besoin d'un endroit pour jouer !","en":"Sure, it's expensive, but kids need a place to play!","spans":[[0,6,"fr_certes_adv"]]},{"speaker":"Papa","fr":"Tu parles comme un conseiller ! D'ailleurs, regarde : Mme Lefort se lève.","en":"You sound like a councilman! Besides, look: Mrs. Lefort is standing up.","spans":[[32,42,"fr_d_ailleurs_adv"]]},{"speaker":"Mme Lefort","fr":"Nous allons voter. Cependant, je le rappelle : ce parc est absolument nécessaire.","en":"We will now vote. However, let me remind you: this playground is absolutely necessary.","spans":[[19,28,"fr_cependant_adv"],[59,69,"fr_absolument_adv"]]},{"speaker":"Papa","fr":"Presque toutes les mains sont levées… Finalement, c'est oui. Heureusement !","en":"Almost every hand is up… In the end, it's a yes. Thank goodness!","spans":[[38,48,"fr_finalement_adv"],[61,73,"fr_heureusement_adv"]]},{"speaker":"Tom","fr":"Tu es contente, Léa ?","en":"Are you happy, Léa?","spans":[]},{"speaker":"Léa","fr":"Complètement ! Et je serai certainement la première sur le toboggan !","en":"Totally! And I'll definitely be the first one on the slide!","spans":[[0,12,"fr_completement_adv"],[27,39,"fr_certainement_adv"]]}]}],"mairie/cour":[{"id":"V_mairie_cour_01","title":"La foire des associations","premise":"Mom takes Tom and Léa to the village clubs fair in the town hall courtyard.","cefr":"B2","lines":[{"speaker":"Maman","fr":"Aujourd'hui, toutes les associations de la commune sont dans la cour de la mairie.","en":"Today all the town's clubs and charities are in the town hall courtyard.","spans":[[43,50,"fr_commune_noun"]]},{"speaker":"Léa","fr":"On dirait une foire ! Il y a des stands partout.","en":"It's like a fair! There are booths everywhere.","spans":[[14,19,"fr_foire_noun"]]},{"speaker":"Maman","fr":"Ce stand collecte des jouets pour les familles qui vivent dans la pauvreté.","en":"This booth is collecting toys for families living in poverty.","spans":[[66,74,"fr_pauvrete_noun"]]},{"speaker":"Tom","fr":"Je peux donner mon vieux camion ?","en":"Can I give my old truck?","spans":[]},{"speaker":"Maman","fr":"Bien sûr. Merci pour ta générosité ! C'est ça, la solidarité.","en":"Of course. Thank you for your generosity! That's what solidarity is.","spans":[[24,34,"fr_generosite_noun"],[50,60,"fr_solidarite_noun"]]},{"speaker":"Léa","fr":"Et là-bas, pourquoi les filles ont des pancartes ?","en":"And over there, why do the girls have signs?","spans":[]},{"speaker":"Maman","fr":"C'est une petite manifestation pour l'égalité au club de foot : les filles veulent aussi un terrain le samedi.","en":"It's a little demonstration for equality at the soccer club: the girls want a field on Saturdays too.","spans":[[17,30,"fr_manifestation_noun"],[38,45,"fr_egalite_noun"]]},{"speaker":"Tom","fr":"Elles ont raison ! Une inégalité, ce n'est pas juste.","en":"They're right! Inequality isn't fair.","spans":[[23,32,"fr_inegalite_noun"]]},{"speaker":"Léa","fr":"Regarde les scouts avec leurs foulards : on dirait une tribu !","en":"Look at the scouts with their scarves: they look like a tribe!","spans":[[55,60,"fr_tribu_noun"]]},{"speaker":"Maman","fr":"Ha ha ! Et ils comptent sur votre participation au grand jeu de cet après-midi.","en":"Ha ha! And they're counting on you to take part in the big game this afternoon.","spans":[[34,47,"fr_participation_noun"]]}]}],"mairie/fetes":[{"id":"V_mairie_fetes_01","title":"Le loto de la salle des fêtes","premise":"Dad and the children help set up the village hall for the Saturday bingo night.","cefr":"B2","lines":[{"speaker":"Papa","fr":"Ce soir, c'est le loto de la salle des fêtes. Tous les gens qui aident sont bénévoles.","en":"Tonight is the village hall bingo. Everyone helping out is a volunteer.","spans":[[76,85,"fr_benevole_adj"]]},{"speaker":"Tom","fr":"Bénévoles ? Alors personne n'est payé ?","en":"Volunteers? So nobody gets paid?","spans":[[0,9,"fr_benevole_adj"]]},{"speaker":"Papa","fr":"Personne. Mais l'entrée est payante : deux euros par carton.","en":"Nobody. But you pay to get in: two euros a card.","spans":[[28,35,"fr_payant_adj"]]},{"speaker":"Léa","fr":"Et ça rapporte beaucoup d'argent ?","en":"And does it make a lot of money?","spans":[]},{"speaker":"Papa","fr":"Oui, le loto est très rentable. L'argent va au club de foot des enfants.","en":"Yes, bingo is very profitable. The money goes to the children's soccer club.","spans":[[22,30,"fr_rentable_adj"]]},{"speaker":"Tom","fr":"Regarde le pompier : il porte fièrement son casque tout neuf !","en":"Look at the firefighter: he's proudly wearing his brand-new helmet!","spans":[[30,39,"fr_fierement_adv"]]},{"speaker":"Léa","fr":"Et le vieux monsieur, là-bas, il dort paisiblement sur sa chaise.","en":"And the old man over there is sleeping peacefully on his chair.","spans":[[38,50,"fr_paisiblement_adv"]]},{"speaker":"Papa","fr":"Ce piano est carrément trop lourd pour moi. Tom, tu m'aides ?","en":"This piano is way too heavy for me. Tom, will you help me?","spans":[[13,22,"fr_carrement_adv"]]}]}],"mairie/guichets":[{"id":"C_R_admin_01","title":"La carte d'identité perdue","premise":"A woman goes to the town hall to replace her lost identity card.","cefr":"A2","lines":[{"speaker":"Mme Martin","fr":"Bonjour, j'ai perdu ma carte d'identité. Qu'est-ce que je dois faire ?","en":"Hello, I've lost my identity card. What do I need to do?","spans":[[31,39,"fr_identite_noun"]]},{"speaker":"l'agent","fr":"Vous devez remplir une déclaration de perte, et apporter des documents.","en":"You need to fill in a declaration of loss and bring some documents.","spans":[]},{"speaker":"Mme Martin","fr":"Lesquels ?","en":"Which ones?","spans":[]},{"speaker":"l'agent","fr":"Une photo, un justificatif de domicile, et on prendra vos empreintes ici.","en":"A photo, proof of address, and we'll take your fingerprints here.","spans":[]},{"speaker":"Mme Martin","fr":"Je dois aller dans quel département ? Je suis née à Lyon.","en":"Which department do I have to go to? I was born in Lyon.","spans":[[24,35,"fr_departement_noun"]]},{"speaker":"l'agent","fr":"Non, c'est ici, à la mairie du quinzième arrondissement.","en":"No, it's here, at the town hall of the 15th arrondissement.","spans":[[41,55,"fr_arrondissement_noun"]]},{"speaker":"Mme Martin","fr":"Et ça prend combien de temps ?","en":"And how long does it take?","spans":[]},{"speaker":"l'agent","fr":"Trois semaines. L'agence nationale vous enverra un SMS. Avec certitude, avant les vacances !","en":"Three weeks. The national agency will send you a text. Definitely before vacation!","spans":[[18,24,"fr_agence_noun"]]},{"speaker":"Mme Martin","fr":"Ouf ! J'ai acheté un sac d'une nouvelle marque, avec une fermeture : je ne perdrai plus rien !","en":"Phew! I've bought a bag from a new brand, with a zip: I won't lose anything again!","spans":[]}]},{"id":"V_mairie_guichets_01","title":"La carte d'identité de Léa","premise":"Mom takes Léa to the registration office to apply for her first ID card.","cefr":"B2","lines":[{"speaker":"Maman","fr":"Bonjour, nous venons pour la première carte d'identité de ma fille.","en":"Hello, we're here for my daughter's first ID card.","spans":[[46,54,"fr_identite_noun"]]},{"speaker":"Le guichetier","fr":"Très bien. Vous avez son certificat de naissance et une photo ?","en":"Very good. Do you have her birth certificate and a photo?","spans":[[25,35,"fr_certificat_noun"]]},{"speaker":"Léa","fr":"La photo, on l'a faite dans la cabine rouge, là-bas !","en":"We took the photo in the red booth over there!","spans":[]},{"speaker":"Le guichetier","fr":"Parfait. Je cherche votre dossier dans le fichier… Le voilà.","en":"Perfect. I'm looking for your file in the records… Here it is.","spans":[[42,49,"fr_fichier_noun"]]},{"speaker":"Maman","fr":"Vous pouvez confirmer notre rendez-vous de jeudi ?","en":"Can you confirm our appointment on Thursday?","spans":[[12,21,"fr_confirmer_verb"]]},{"speaker":"Le guichetier","fr":"Oui, c'est noté. Vous serez convoquées jeudi pour les empreintes.","en":"Yes, it's written down. You'll be called in on Thursday for the fingerprints.","spans":[]},{"speaker":"Léa","fr":"Pourquoi il y a autant de papiers ?","en":"Why is there so much paperwork?","spans":[]},{"speaker":"Maman","fr":"C'est la vie administrative ! Et après, on passe à l'agence de voyages, juste à côté.","en":"That's official paperwork for you! And afterward we'll stop at the travel agency next door.","spans":[[13,27,"fr_administratif_adj"],[53,59,"fr_agence_noun"]]},{"speaker":"Léa","fr":"Pour aller dans un autre département ?","en":"To go to another département?","spans":[[25,36,"fr_departement_noun"]]},{"speaker":"Maman","fr":"Non, ma chérie, pour aller à l'étranger. C'est pour ça qu'il te faut une pièce d'identité !","en":"No, sweetheart, to go abroad. That's why you need an ID!","spans":[[81,89,"fr_identite_noun"]]}]}],"mairie/parlement":[{"id":"C_R_politics_03","title":"Le jour de l'élection","premise":"Two neighbors meet outside the polling station on election day.","cefr":"B2","lines":[{"speaker":"M. Roussel","fr":"Bonjour ! Vous êtes venue voter ?","en":"Hello! Have you come to vote?","spans":[]},{"speaker":"Mme Chevalier","fr":"Oui, c'est important. L'élection du maire, ça compte !","en":"Yes, it's important. The mayoral election matters!","spans":[[24,32,"fr_election_noun"]]},{"speaker":"M. Roussel","fr":"Moi, je suis partisan de la liste écologiste.","en":"I'm a supporter of the green list.","spans":[]},{"speaker":"Mme Chevalier","fr":"Le vote est secret, je ne dis rien ! Mais j'ai lu toutes les déclarations des candidats.","en":"Voting is secret, I'm not saying anything! But I've read all the candidates' statements.","spans":[[3,7,"fr_vote_noun"]]},{"speaker":"M. Roussel","fr":"Vous avez raison. C'est ça, la démocratie.","en":"You're right. That's democracy.","spans":[[31,41,"fr_democratie_noun"]]},{"speaker":"Mme Chevalier","fr":"Et notre représentant au conseil, il se présente encore ?","en":"And our representative on the council, is he standing again?","spans":[[9,21,"fr_representant_noun"]]},{"speaker":"M. Roussel","fr":"Non, il part au congrès national de son parti.","en":"No, he's off to his party's national congress.","spans":[]},{"speaker":"Mme Chevalier","fr":"Bon, on se retrouve à l'inauguration de la nouvelle médiathèque samedi ?","en":"Right, should we meet at the opening of the new media library on Saturday?","spans":[]},{"speaker":"M. Roussel","fr":"Avec plaisir !","en":"With pleasure!","spans":[]}]},{"id":"V_mairie_parlement_01","title":"La séance du parlement des jeunes","premise":"Tom is a member of the youth parliament, and Léa watches her first debate from the public gallery.","cefr":"C1","lines":[{"speaker":"Léa","fr":"C'est ça, le parlement des jeunes ? On dirait un vrai !","en":"So this is the youth parliament? It looks like a real one!","spans":[[13,22,"fr_parlement_noun"]]},{"speaker":"Tom","fr":"Oui ! Après l'élection, chaque école a envoyé un représentant. Moi, je représente la mienne.","en":"Yes! After the election, every school sent a representative. I represent mine.","spans":[[14,22,"fr_election_noun"],[49,61,"fr_representant_noun"]]},{"speaker":"Léa","fr":"Et pourquoi vous êtes assis en deux groupes ?","en":"And why are you sitting in two groups?","spans":[]},{"speaker":"Tom","fr":"Mon parti est à gauche. Ceux de droite, c'est l'opposition : ils ne sont jamais d'accord avec nous.","en":"My party is on the left. The ones on the right are the opposition: they never agree with us.","spans":[[4,9,"fr_parti_noun"],[48,58,"fr_opposition_noun"]]},{"speaker":"Maman","fr":"C'est normal, c'est la démocratie. On discute, puis on vote.","en":"That's normal, that's democracy. You debate, then you vote.","spans":[[23,33,"fr_democratie_noun"],[55,59,"fr_vote_noun"]]},{"speaker":"Tom","fr":"Aujourd'hui, on vote pour une piste cyclable devant l'école.","en":"Today we're voting on a bike lane in front of the school.","spans":[[16,20,"fr_vote_noun"]]},{"speaker":"Léa","fr":"Alors, vous l'approuvez ?","en":"So, do you approve it?","spans":[[14,23,"fr_approuver_verb"]]},{"speaker":"Tom","fr":"Le vote est terminé… Trente pour, dix contre. C'est approuvé !","en":"The vote is over… Thirty for, ten against. It's approved!","spans":[[3,7,"fr_vote_noun"],[52,60,"fr_approuver_verb"]]},{"speaker":"Maman","fr":"Bravo. Et la prochaine fois, vous écrirez une constitution ?","en":"Well done. And next time will you write a constitution?","spans":[[46,58,"fr_constitution_noun"]]}]}],"mairie/debats":[{"id":"V_mairie_debats_01","title":"Le grand débat","premise":"Tom practices for a school debate contest with Inès while Léa referees with a whistle.","cefr":"C1","lines":[{"speaker":"Léa","fr":"Le débat commence officiellement… maintenant ! Coup de sifflet !","en":"The debate officially starts… now! Whistle!","spans":[[18,32,"fr_officiellement_adv"]]},{"speaker":"Tom","fr":"Franchement, les devoirs le week-end, c'est inutile.","en":"Frankly, homework on weekends is pointless.","spans":[[0,11,"fr_franchement_adv"]]},{"speaker":"Inès","fr":"Je vais te contredire : sans devoirs, on oublie tout le lundi.","en":"I'm going to contradict you: without homework, we forget everything by Monday.","spans":[[11,21,"fr_contredire_verb"]]},{"speaker":"Tom","fr":"Sérieusement ? Tu veux réellement travailler le dimanche ?","en":"Seriously? Do you really want to work on Sunday?","spans":[[0,12,"fr_serieusement_adv"],[23,33,"fr_reellement_adv"]]},{"speaker":"Inès","fr":"Honnêtement, non. Mais il faut parler clairement : c'est essentiellement une question de mémoire.","en":"Honestly, no. But let's be clear: it's essentially a question of memory.","spans":[[0,11,"fr_honnetement_adv"],[38,48,"fr_clairement_adv"],[57,72,"fr_essentiellement_adv"]]},{"speaker":"Tom","fr":"Moi, je suis littéralement épuisé le vendredi soir !","en":"Me, I'm literally exhausted on Friday nights!","spans":[[13,26,"fr_litteralement_adv"]]},{"speaker":"Léa","fr":"Tom, ça, c'est un argument purement personnel. Un point pour Inès !","en":"Tom, that's a purely personal argument. One point for Inès!","spans":[[27,35,"fr_purement_adv"]]},{"speaker":"Inès","fr":"Alors, je t'ai persuadé ?","en":"So, have I persuaded you?","spans":[[12,23,"fr_persuader_verb"]]},{"speaker":"Tom","fr":"Pas du tout ! Mais tu parles bien.","en":"Not at all! But you speak well.","spans":[]}]}],"mairie/commission":[{"id":"C_R_adv_logic_02","title":"L'offre d'emploi","premise":"Two friends talk about a job offer that one of them has decided to turn down.","cefr":"B2","lines":[{"speaker":"Élise","fr":"Alors, tu as accepté le poste à Lyon ?","en":"So, did you accept the job in Lyon?","spans":[]},{"speaker":"Thibault","fr":"Non. J'ai envoyé mon refus ce matin.","en":"No. I sent my refusal this morning.","spans":[[21,26,"fr_refus_noun"]]},{"speaker":"Élise","fr":"Vraiment ? Tu en avais vaguement parlé, mais je pensais que tu étais content.","en":"Really? You'd mentioned it vaguely, but I thought you were pleased.","spans":[[23,32,"fr_vaguement_adv"]]},{"speaker":"Thibault","fr":"Le salaire était bon. Toutefois, il fallait partir loin de ma famille.","en":"The salary was good. However, I'd have had to move far from my family.","spans":[]},{"speaker":"Élise","fr":"Je comprends. Contrairement à moi, tu as toujours mis ta famille en premier.","en":"I understand. Unlike me, you've always put your family first.","spans":[[14,27,"fr_contrairement_adv"]]},{"speaker":"Thibault","fr":"Je regrette un peu, sincèrement. Néanmoins, c'est définitivement le bon choix.","en":"I'm a bit sorry, honestly. Nevertheless, it's definitely the right choice.","spans":[[33,42,"fr_neanmoins_adv"],[50,64,"fr_definitivement_adv"]]},{"speaker":"Élise","fr":"Et ton patron ? Il est au courant ?","en":"And your boss? Does he know?","spans":[]},{"speaker":"Thibault","fr":"Oui, je lui ai expliqué proprement, il a compris.","en":"Yes, I explained it to him properly, he understood.","spans":[]}]},{"id":"V_mairie_commission_01","title":"Le nouveau parc","premise":"Dad attends the planning committee with the children to see the plans for a new park.","cefr":"C1","lines":[{"speaker":"La présidente","fr":"Voici le plan du nouveau parc, à côté de l'école.","en":"Here's the plan for the new park, next to the school.","spans":[]},{"speaker":"Léa","fr":"Je le vois vaguement… le dessin est tout flou !","en":"I can only vaguely see it… the drawing is all blurry!","spans":[[11,20,"fr_vaguement_adv"]]},{"speaker":"Papa","fr":"Mets tes lunettes correctement, ma chérie.","en":"Put your glasses on properly, sweetheart.","spans":[[18,30,"fr_correctement_adv"]]},{"speaker":"La présidente","fr":"Le parc sera strictement interdit aux voitures. Néanmoins, il y aura un parking à vélos.","en":"The park will be strictly closed to cars. Nevertheless, there will be a bike rack.","spans":[[13,24,"fr_strictement_adv"],[48,57,"fr_neanmoins_adv"]]},{"speaker":"Léa","fr":"Curieusement, il n'y a pas de toboggan sur le plan.","en":"Curiously, there's no slide on the plan.","spans":[[0,12,"fr_curieusement_adv"]]},{"speaker":"La présidente","fr":"Contrairement à l'ancien parc, celui-ci aura une grande aire de jeux. Pas nécessairement un toboggan, mais une tyrolienne.","en":"Unlike the old park, this one will have a big playground. Not necessarily a slide, but a zip line.","spans":[[0,13,"fr_contrairement_adv"],[74,88,"fr_necessairement_adv"]]},{"speaker":"Papa","fr":"Et c'est définitivement décidé ?","en":"And is it definitely decided?","spans":[[9,23,"fr_definitivement_adv"]]},{"speaker":"La présidente","fr":"Oui. Dorénavant, le terrain appartient à la commune.","en":"Yes. From now on, the land belongs to the town.","spans":[[5,15,"fr_dorenavant_adv"]]},{"speaker":"Léa","fr":"Une tyrolienne, c'est encore mieux !","en":"A zip line is even better!","spans":[]},{"speaker":"Papa","fr":"Tu vois ? Tu n'as même pas eu besoin de rétorquer.","en":"See? You didn't even need to talk back.","spans":[[40,49,"fr_retorquer_verb"]]}]}],"mairie/associations":[{"id":"V_mairie_associations_01","title":"Quel club choisir ?","premise":"Mom and the children visit the clubs' hall, where each club has a table.","cefr":"B2","lines":[{"speaker":"Maman","fr":"Bienvenue à la maison des associations ! Chaque club a sa table.","en":"Welcome to the clubs' hall! Each club has its own table.","spans":[]},{"speaker":"Tom","fr":"Je veux adhérer au club d'escalade ! Il y a un mur dans la salle.","en":"I want to join the climbing club! There's a wall in the hall.","spans":[[8,15,"fr_adherer_verb"]]},{"speaker":"Maman","fr":"Attention, il y a une restriction : il faut avoir douze ans.","en":"Careful, there's a restriction: you have to be twelve.","spans":[[22,33,"fr_restriction_noun"]]},{"speaker":"Tom","fr":"J'ai onze ans et demi… presque !","en":"I'm eleven and a half… almost!","spans":[]},{"speaker":"Léa","fr":"Moi, j'aime le club de foot : il y a la parité, autant de filles que de garçons.","en":"I like the soccer club: there's parity, as many girls as boys.","spans":[[40,46,"fr_parite_noun"]]},{"speaker":"Maman","fr":"Et le cours de citoyenneté explique le devoir civique : voter, aider ses voisins…","en":"And the citizenship class explains civic duty: voting, helping your neighbors…","spans":[[15,26,"fr_citoyennete_noun"],[46,53,"fr_civique_adj"]]},{"speaker":"Tom","fr":"Liberté, égalité, fraternité ! C'est écrit sur la mairie.","en":"Liberty, equality, fraternity! It's written on the town hall.","spans":[[18,28,"fr_fraternite_noun"]]},{"speaker":"Léa","fr":"Pourquoi ce monsieur porte un masque ?","en":"Why is that man wearing a mask?","spans":[]},{"speaker":"Maman","fr":"C'est pour le jeu du club de théâtre : il garde l'anonymat jusqu'à la fin.","en":"It's for the drama club's game: he stays anonymous until the end.","spans":[[50,58,"fr_anonymat_noun"]]},{"speaker":"Tom","fr":"Ici, c'est une salle communale : tout le monde peut venir. C'est bon pour la sociabilité !","en":"This is a town hall: anyone can come. It's good for making friends!","spans":[[21,30,"fr_communal_adj"],[77,88,"fr_sociabilite_noun"]]}]}],"mairie/expo":[{"id":"V_mairie_expo_01","title":"L'exposition des voyageurs","premise":"Grandpa takes Léa to the town exhibition about people who traveled and settled in the region.","cefr":"C1","lines":[{"speaker":"Léa","fr":"Papi, pourquoi il y a une tente au milieu de l'exposition ?","en":"Grandpa, why is there a tent in the middle of the exhibition?","spans":[]},{"speaker":"Papi","fr":"C'est une tente de peuple nomade : ils changent de maison avec les saisons.","en":"It's a tent from a nomadic people: they move home with the seasons.","spans":[[26,32,"fr_nomade_adj"]]},{"speaker":"Léa","fr":"Comme les oiseaux migrateurs, là-haut, sous la verrière !","en":"Like the migrating birds up there under the skylight!","spans":[[18,28,"fr_migrateur_adj"]]},{"speaker":"Papi","fr":"Exactement. Et cette vitrine montre des fruits tropicaux, rapportés par un explorateur.","en":"Exactly. And this display case shows tropical fruit brought back by an explorer.","spans":[[47,56,"fr_tropical_adj"]]},{"speaker":"Léa","fr":"Et le monsieur avec le chapeau haut de forme ?","en":"And the man in the top hat?","spans":[]},{"speaker":"Papi","fr":"Un comte, d'une famille aristocratique. Il vivait dans le château, avant le quartier résidentiel.","en":"A count, from an aristocratic family. He lived in the château, before the housing estate.","spans":[[24,38,"fr_aristocratique_adj"],[85,96,"fr_residentiel_adj"]]},{"speaker":"Léa","fr":"C'est un musée anthropologique, alors ?","en":"So it's an anthropology museum?","spans":[[15,30,"fr_anthropologique_adj"]]},{"speaker":"Papi","fr":"Un peu ! Ta question est bien fondée.","en":"Sort of! Your question is well founded.","spans":[[30,36,"fr_fonde_adj"]]},{"speaker":"Léa","fr":"Et cette dame avec la pancarte ?","en":"And the lady with the sign?","spans":[]},{"speaker":"Papi","fr":"La première militante féministe du village. Elle a obtenu une école pour les filles.","en":"The village's first feminist activist. She got a school for girls.","spans":[[22,31,"fr_feministe_adj"]]}]},{"id":"C_R_adj_relation_07","title":"Le documentaire nature","premise":"Two friends talk about a documentary on migratory birds and nomadic peoples.","cefr":"C2","lines":[{"speaker":"Clément","fr":"Tu as vu le documentaire sur les oiseaux migrateurs ?","en":"Did you see the documentary about migratory birds?","spans":[[41,51,"fr_migrateur_adj"]]},{"speaker":"Inès","fr":"Oui ! Ils traversent la mer jusqu'aux forêts tropicales.","en":"Yes! They cross the sea all the way to the tropical forests.","spans":[[45,55,"fr_tropical_adj"]]},{"speaker":"Clément","fr":"Et la deuxième partie, sur les peuples nomades du désert.","en":"And the second part, about the nomadic peoples of the desert.","spans":[[39,46,"fr_nomade_adj"]]},{"speaker":"Inès","fr":"Fascinant. Le guide était très croyant, il priait cinq fois par jour.","en":"Fascinating. The guide was very devout, he prayed five times a day.","spans":[[31,38,"fr_croyant_adj"]]},{"speaker":"Clément","fr":"Le réalisateur est connu pour ses films féministes, non ?","en":"The director is known for his feminist movies, isn't he?","spans":[[40,50,"fr_feministe_adj"]]},{"speaker":"Inès","fr":"Oui. Et il a fait un film sur un vieux professeur marxiste, aussi.","en":"Yes. And he made a movie about an old Marxist professor, too.","spans":[[50,58,"fr_marxiste_adj"]]},{"speaker":"Clément","fr":"On le projette à la salle communale samedi, pour la soirée civique du quartier.","en":"They're showing it at the village hall on Saturday, for the neighborhood civic evening.","spans":[]},{"speaker":"Inès","fr":"J'y serai !","en":"I'll be there!","spans":[]}]}],"mairie/nations":[{"id":"V_mairie_nations_01","title":"Le déjeuner des villes jumelles","premise":"The family helps at the lunch for the delegations from the twin towns.","cefr":"B2","lines":[{"speaker":"Maman","fr":"Aujourd'hui, c'est le déjeuner des délégations : un vrai repas multinational !","en":"Today is the delegations' lunch: a truly multinational meal!","spans":[[63,76,"fr_multinational_adj"]]},{"speaker":"Tom","fr":"Il y a du fromage suisse avec des trous et du sirop d'érable québécois !","en":"There's Swiss cheese with holes and maple syrup from Quebec!","spans":[[18,24,"fr_suisse_adj"],[61,70,"fr_quebecois_adj"]]},{"speaker":"Léa","fr":"Et la dame blonde, elle vient d'où ?","en":"And where's the blonde lady from?","spans":[]},{"speaker":"Maman","fr":"De Suède : c'est la délégation scandinave. À côté, ce sont nos amis roumains.","en":"From Sweden: that's the Scandinavian delegation. Next to them are our Romanian friends.","spans":[[31,41,"fr_scandinave_adj"],[68,76,"fr_roumain_adj"]]},{"speaker":"Tom","fr":"Et ce fromage-là, il est corse ?","en":"And that cheese, is it from Corsica?","spans":[[25,30,"fr_corse_adj"]]},{"speaker":"Maman","fr":"Oui. La Corse est une île, mais elle fait partie de la France métropolitaine.","en":"Yes. Corsica is an island, but it's part of metropolitan France.","spans":[[8,13,"fr_corse_adj"],[62,76,"fr_metropolitain_adj"]]},{"speaker":"Léa","fr":"Pourquoi le monsieur parle de petit-déjeuner continental ?","en":"Why is the man talking about a continental breakfast?","spans":[[45,56,"fr_continental_adj"]]},{"speaker":"Maman","fr":"Parce que demain matin, il y aura des croissants et du café pour tout le monde.","en":"Because tomorrow morning there'll be croissants and coffee for everyone.","spans":[]},{"speaker":"Tom","fr":"Et la carte, là, avec les eaux territoriales ?","en":"And the map over there, with the territorial waters?","spans":[[31,44,"fr_territorial_adj"]]},{"speaker":"Maman","fr":"C'est pour la réunion de cet après-midi… mais d'abord, on mange !","en":"That's for this afternoon's meeting… but first, we eat!","spans":[]}]},{"id":"C_R_adj_relation_08","title":"Le voyage de noces","premise":"A newly married couple plan their honeymoon across Europe.","cefr":"C2","lines":[{"speaker":"Élodie","fr":"Pour le voyage de noces, on part dans les pays scandinaves ?","en":"For the honeymoon, should we go to the Scandinavian countries?","spans":[[47,58,"fr_scandinave_adj"]]},{"speaker":"Adrien","fr":"Il fait froid ! Pourquoi pas la Corse ? Les plages corses sont magnifiques.","en":"It's cold! Why not Corsica? Corsican beaches are gorgeous.","spans":[[32,37,"fr_corse_adj"],[51,57,"fr_corse_adj"]]},{"speaker":"Élodie","fr":"Ou les Highlands écossais !","en":"Or the Scottish Highlands!","spans":[]},{"speaker":"Adrien","fr":"Ou la Roumanie : ma grand-mère est roumaine, j'aimerais voir son village.","en":"Or Romania: my grandmother is Romanian, I'd like to see her village.","spans":[[35,43,"fr_roumain_adj"]]},{"speaker":"Élodie","fr":"Quelle bonne idée ! On partirait de la France métropolitaine en train ?","en":"What a good idea! Should we leave mainland France by train?","spans":[[46,60,"fr_metropolitain_adj"]]},{"speaker":"Adrien","fr":"Oui. Et on passerait par Vienne.","en":"Yes. And we'd go via Vienna.","spans":[]},{"speaker":"Élodie","fr":"Il faut d'abord payer la taxe foncière de la maison...","en":"We need to pay the property tax on the house first...","spans":[]},{"speaker":"Adrien","fr":"On a juste assez. Et pour la Corse, l'année prochaine, on réserve le ferry tôt !","en":"We've just got enough. And for Corsica next year, we'll book the ferry early!","spans":[[29,34,"fr_corse_adj"]]}]}],"mairie/civique":[{"id":"C_R_society_02","title":"L'association du quartier","premise":"Two neighbors talk about joining a local association that helps people.","cefr":"A2","lines":[{"speaker":"Nathalie","fr":"Tu es membre de l'association « Main dans la main » ?","en":"Are you a member of the \"Hand in Hand\" association?","spans":[[6,12,"fr_membre_noun"],[18,29,"fr_association_noun"]]},{"speaker":"Omar","fr":"Oui, depuis un an. On aide les personnes âgées de la communauté.","en":"Yes, for a year. We help elderly people in the community.","spans":[[53,63,"fr_communaute_noun"]]},{"speaker":"Nathalie","fr":"C'est formidable. La population du quartier vieillit.","en":"That's wonderful. The local population is getting older.","spans":[[21,31,"fr_population_noun"]]},{"speaker":"Omar","fr":"Oui. Et chacun a le droit de vivre chez soi, avec dignité.","en":"Yes. And everyone has the right to live at home, with dignity.","spans":[[20,25,"fr_droit_noun"]]},{"speaker":"Nathalie","fr":"Je voudrais vous rejoindre. Je suis libre le samedi.","en":"I'd like to join you. I'm free on Saturdays.","spans":[]},{"speaker":"Omar","fr":"Super ! L'union fait la force !","en":"Great! There's strength in numbers!","spans":[[10,15,"fr_union_noun"]]},{"speaker":"Nathalie","fr":"Et c'est important pour notre société.","en":"And it's important for our society.","spans":[[30,37,"fr_societe_noun"]]},{"speaker":"Omar","fr":"Oui. Et pour moi, c'est aussi une liberté : je choisis mes heures.","en":"Yes. And for me it's freedom too: I choose my hours.","spans":[[34,41,"fr_liberte_noun"]]}]}],"mairie/conseil":[{"id":"C_R_adv_logic_01","title":"On va au concert ?","premise":"Two friends decide whether to go to a concert on the weekend.","cefr":"A1","lines":[{"speaker":"Hugo","fr":"Tu viens au concert samedi ?","en":"Are you coming to the concert on Saturday?","spans":[]},{"speaker":"Sarah","fr":"Peut-être. Je n'ai pas vraiment d'argent ce mois-ci.","en":"Maybe. I don't really have any money this month.","spans":[[0,9,"fr_peut_etre_adv"],[19,22,"fr_pas_adv"],[23,31,"fr_vraiment_adv"]]},{"speaker":"Hugo","fr":"Les billets coûtent seulement dix euros !","en":"The tickets are only ten euros!","spans":[[20,29,"fr_seulement_adv"]]},{"speaker":"Sarah","fr":"Ah bon ? Alors, j'ai assez d'argent. Je viens !","en":"Really? Then I've got enough money. I'm coming!","spans":[[21,26,"fr_assez_adv"]]},{"speaker":"Hugo","fr":"Enfin une bonne nouvelle !","en":"Good news at last!","spans":[[0,5,"fr_enfin_adv"]]},{"speaker":"Sarah","fr":"Donc on se retrouve à la gare ?","en":"So we'll meet at the station?","spans":[[0,4,"fr_donc_adv"]]},{"speaker":"Hugo","fr":"Oui, ainsi on prend le même train.","en":"Yes, that way we'll catch the same train.","spans":[[5,10,"fr_ainsi_adv"]]},{"speaker":"Sarah","fr":"Parfait. Ne sois pas en retard !","en":"Perfect. Don't be late!","spans":[[17,20,"fr_pas_adv"]]}]}],"mairie/archives":[{"id":"C_R_adj_relation_01","title":"Le correspondant allemand","premise":"A girl tells her mother about the German exchange student coming to stay.","cefr":"A1","lines":[{"speaker":"Juliette","fr":"Maman, mon correspondant allemand arrive lundi !","en":"Mom, my German exchange partner arrives on Monday!","spans":[[25,33,"fr_allemand_adj"]]},{"speaker":"Maman","fr":"Super ! Il parle français ?","en":"Great! Does he speak French?","spans":[[17,25,"fr_francais_adj"]]},{"speaker":"Juliette","fr":"Un peu. Il apprend aussi le russe, il est très doué.","en":"A little. He's learning Russian too, he's very gifted.","spans":[[28,33,"fr_russe_adj"]]},{"speaker":"Maman","fr":"On lui fait découvrir la cuisine locale ? Il n'a jamais goûté de plats français.","en":"Should we introduce him to local food? He's never tried French dishes.","spans":[[33,39,"fr_local_adj"],[71,79,"fr_francais_adj"]]},{"speaker":"Juliette","fr":"Oui ! Et le lycée organise une sortie culturelle au musée.","en":"Yes! And school is organizing a cultural trip to the museum.","spans":[[38,48,"fr_culturel_adj"]]},{"speaker":"Maman","fr":"C'est un échange international, c'est une chance.","en":"It's an international exchange, it's a great opportunity.","spans":[[17,30,"fr_international_adj"]]},{"speaker":"Juliette","fr":"Oui. Je veux travailler dans un pays étranger plus tard.","en":"Yes. I want to work in a foreign country later on.","spans":[[37,45,"fr_etranger_adj"]]},{"speaker":"Maman","fr":"Peut-être au Parlement européen !","en":"Maybe at the European Parliament!","spans":[[23,31,"fr_europeen_adj"]]}]}],"mairie/cartes":[{"id":"C_R_adj_relation_02","title":"Le journal du matin","premise":"A couple read the newspaper over breakfast and talk about the news.","cefr":"A2","lines":[{"speaker":"Martine","fr":"Tu as lu ? Le championnat mondial de foot commence demain.","en":"Did you read? The soccer world championship starts tomorrow.","spans":[[26,33,"fr_mondial_adj"]]},{"speaker":"Gérard","fr":"Oui. L'équipe nationale joue contre une équipe américaine.","en":"Yes. The national team is playing an American team.","spans":[[14,23,"fr_national_adj"],[47,57,"fr_americain_adj"]]},{"speaker":"Martine","fr":"Et dans les pages politiques, rien de nouveau ?","en":"And in the politics pages, nothing new?","spans":[[18,28,"fr_politique_adj"]]},{"speaker":"Gérard","fr":"Des débats sur la réforme sociale, comme d'habitude.","en":"Debates about social reform, as usual.","spans":[[26,33,"fr_social_adj"]]},{"speaker":"Martine","fr":"Il y a aussi un article sur divers festivals de musique cet été.","en":"There's also an article on various music festivals this summer.","spans":[[28,34,"fr_divers_adj"]]},{"speaker":"Gérard","fr":"En général, je saute ces pages. Mais un en particulier m'intéresse : le festival de jazz.","en":"I generally skip those pages. But one in particular interests me: the jazz festival.","spans":[[3,10,"fr_general_adj"],[43,54,"fr_particulier_adj"]]},{"speaker":"Martine","fr":"On y va ensemble ?","en":"Should we go together?","spans":[]},{"speaker":"Gérard","fr":"Avec plaisir !","en":"With pleasure!","spans":[]}]}]};
